import React, { useState, useEffect } from 'react';
import { getStore2AllSales, createStore2Sale } from '../../services/store2Service';
import SaleTable from '../tables/SaleTable';

const SalesOperations = () => {
    const [sales, setSales] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    const [saleForm, setSaleForm] = useState({
        productCode: '',
        category: '',
        productName: '',
        size: '',
        color: '',
        quantity: 0,
        unitPrice: 0,
        totalPrice: 0
    });

    useEffect(() => {
        fetchSales();
    }, []);

    const fetchSales = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await getStore2AllSales();

            if (!response || !response.success) {
                throw new Error(response?.message || 'Satış verisi alınamadı');
            }

            setSales(Array.isArray(response.data) ? response.data : []);
        } catch (err) {
            console.error('Satış verisi yüklenirken hata:', err);
            setError(err.message || 'Satış verileri yüklenirken bir hata oluştu');
            setSales([]);
        } finally {
            setLoading(false);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            const response = await createStore2Sale(saleForm);
            if (response.success) {
                alert('Satış başarıyla oluşturuldu');
                fetchSales();
                setSaleForm({
                    productCode: '',
                    category: '',
                    productName: '',
                    size: '',
                    color: '',
                    quantity: 0,
                    unitPrice: 0,
                    totalPrice: 0
                });
            } else {
                setError(response.message);
            }
        } catch (err) {
            setError('Satış oluşturulurken bir hata oluştu');
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setSaleForm(prev => {
            const newForm = { ...prev, [name]: value };
            if (name === 'quantity' || name === 'unitPrice') {
                newForm.totalPrice = newForm.quantity * newForm.unitPrice;
            }
            return newForm;
        });
    };

    if (loading) {
        return (
            <div className="flex justify-center items-center h-screen">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500"></div>
            </div>
        );
    }

    return (
        <div className="p-6">
            <h1 className="text-3xl font-bold mb-8">Store 2 - Satış İşlemleri</h1>

            {/* Satış Oluşturma Formu */}
            <div className="bg-white rounded-lg shadow-md p-6 mb-8">
                <h2 className="text-xl font-bold mb-4">Yeni Satış Ekle</h2>
                {error && (
                    <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                        {error}
                    </div>
                )}
                <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <input
                        type="text"
                        name="productCode"
                        placeholder="Ürün Kodu"
                        className="border p-2 rounded"
                        value={saleForm.productCode}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="category"
                        placeholder="Kategori"
                        className="border p-2 rounded"
                        value={saleForm.category}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="productName"
                        placeholder="Ürün Adı"
                        className="border p-2 rounded"
                        value={saleForm.productName}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="size"
                        placeholder="Beden"
                        className="border p-2 rounded"
                        value={saleForm.size}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="text"
                        name="color"
                        placeholder="Renk"
                        className="border p-2 rounded"
                        value={saleForm.color}
                        onChange={handleInputChange}
                        required
                    />
                    <input
                        type="number"
                        name="quantity"
                        placeholder="Miktar"
                        className="border p-2 rounded"
                        value={saleForm.quantity}
                        onChange={handleInputChange}
                        required
                        min="1"
                    />
                    <input
                        type="number"
                        name="unitPrice"
                        placeholder="Birim Fiyat"
                        className="border p-2 rounded"
                        value={saleForm.unitPrice}
                        onChange={handleInputChange}
                        required
                        min="0"
                    />
                    <div className="border p-2 rounded bg-gray-50">
                        Toplam Fiyat: {new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY' })
                            .format(saleForm.totalPrice)}
                    </div>
                    <div className="md:col-span-2">
                        <button 
                            type="submit" 
                            className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600"
                        >
                            Satış Ekle
                        </button>
                    </div>
                </form>
            </div>

            {/* Satış Listesi */}
            <div className="bg-white rounded-lg shadow-md p-6">
                <h2 className="text-xl font-bold mb-4">Satış Listesi</h2>
                {sales.length === 0 ? (
                    <div className="text-center text-gray-500 py-4">
                        Henüz satış kaydı bulunmamaktadır.
                    </div>
                ) : (
                    <SaleTable sales={sales} />
                )}
            </div>
        </div>
    );
};

export default SalesOperations;
